    input wire [31:0] a_i,
    input wire [31:0] b_i,
    output reg valid_o,
    output reg [5:0] y_o
);

function [1:0] fa3;
    input x; input y; input z;
    begin
        fa3 = {(x & y) | (x & z) | (y & z), x ^ y ^ z};
    end
endfunction

function [1:0] ha2;
    input x; input y;
    begin
        ha2 = {x & y, x ^ y};
    end
endfunction

wire [1:0] g0 = fa3(a_i[0],  a_i[1],  a_i[2]);
wire [1:0] g1 = fa3(a_i[3],  a_i[4],  a_i[5]);
