wire [1:0] g3 = fa3(a_i[9],  a_i[10], a_i[11]);
wire [1:0] g4 = fa3(a_i[12], a_i[13], a_i[14]);
wire [1:0] g5 = fa3(a_i[15], a_i[16], a_i[17]);
